<?php
$isStudent=($portfolio['role']??'')==='student';
$displayName=(int)$portfolio['show_public_name']===1 ? (($portfolio['display_name']??'')?:$portfolio['full_name']) : ($isStudent?'متعلم/ة':'ملف إنجاز مهني');
$evidence=array_values(array_filter($portfolio['evidence']??[],static fn(array $item):bool=>(int)($item['section_id']??0)===(int)$section['id']));
$sectionIndex=1; foreach (($portfolio['sections']??[]) as $index=>$candidate) if ((int)$candidate['id']===(int)$section['id']) { $sectionIndex=$index+1; break; }
$previous=$portfolio['sections'][$sectionIndex-2]??null; $next=$portfolio['sections'][$sectionIndex]??null;
$selectedTemplate=TemplateCatalog::find((string)($portfolio['template_id']??'')); $templateFamily=$selectedTemplate['family']??'orbit';
$parentTitle=''; foreach (($portfolio['sections']??[]) as $candidate) if ((int)$candidate['id']===(int)($section['parent_id']??0)) { $parentTitle=(string)$candidate['title']; break; }
?>
<?php $theme=subject_theme((string)($section['subject_theme']??'general'),(string)$section['title']); ?>
<section class="section-view-page role-<?= $isStudent?'student':'teacher' ?> template-family-<?= e($templateFamily) ?> <?= e($theme['class']) ?> <?= ($portfolio['appearance_mode']??'light')==='dark'?'presentation-dark':'' ?>" style="--public-bg:<?= e($portfolio['background_color']??'#fbf7ef') ?>;--public-accent:<?= e($theme['accent']) ?>;--subject-bg:<?= e($theme['bg']) ?>;--subject-accent:<?= e($theme['accent']) ?>;--public-font:<?= e($portfolio['font_family']??'system-ui') ?>">
    <header class="section-view-topbar"><a class="brand" href="/p/<?= e($token) ?>"><span class="brand-word">أثر<span>.</span></span></a><div class="section-view-actions"><a class="button button-quiet" href="/p/<?= e($token) ?>">العودة إلى الملف</a><a class="button button-gold" href="/p/<?= e($token) ?>?print=1">طباعة الملف</a></div></header>
    <main class="section-view-main">
        <div class="section-view-breadcrumb"><span>القسم <?= str_pad((string)$sectionIndex,2,'0',STR_PAD_LEFT) ?></span><?php if ($parentTitle): ?><span> / </span><strong><?= e($parentTitle) ?></strong><?php endif; ?><span> / </span><strong><?= e($portfolio['title']) ?></strong></div>
        <article class="section-view-card">
            <header><span class="eyebrow"><?= $isStudent?'ملف إنجاز دراسي':'ملف إنجاز مهني' ?> · <?= e($displayName) ?></span><div class="section-view-heading"><h1><?= e($section['title']) ?></h1><span class="section-subject-scene <?= e($theme['class']) ?>" style="--subject-accent:<?= e($theme['accent']) ?>" aria-hidden="true"><?= subject_scene_svg((string)($section['subject_theme']??'general'),(string)$section['title']) ?></span></div><div class="section-view-accent"></div></header>
            <div class="section-view-body"><?php if (trim((string)$section['body'])!==''): ?><?= nl2br(e($section['body'])) ?><?php else: ?><p class="public-empty-section">لا يوجد وصف لهذا القسم.</p><?php endif; ?></div>
            <?php if ($evidence): ?><section class="section-view-evidence"><div class="section-view-subheading"><span class="card-label">شواهد القسم</span><h2>أدلة مختارة مرتبطة بهذا القسم</h2></div><div class="public-evidence-grid"><?php foreach ($evidence as $item): ?><article class="public-evidence <?= str_starts_with($item['mime_type'],'image/')?'public-evidence-image-card':'public-evidence-document-card' ?>"><span class="public-evidence-icon"><?= str_starts_with($item['mime_type'],'image/')?'▧':'▤' ?></span><?php if (str_starts_with($item['mime_type'],'image/')): ?><img class="public-evidence-thumb" loading="lazy" src="/p/<?= e($token) ?>/evidence/<?= (int)$item['id'] ?>" alt="<?= e($item['title']) ?>"><?php endif; ?><?php if (!empty($item['source_url'])): ?><a class="public-evidence-link" href="/p/<?= e($token) ?>/evidence/<?= (int)$item['id'] ?>" target="_blank" rel="noopener noreferrer">فتح <?= $item['source_kind']==='drive'?'ملف Google Drive':'الرابط' ?> ↗</a><?php endif; ?><div><?php if (!empty($item['evidence_type'])): ?><span class="evidence-subtype-badge"><?= e($item['evidence_type']) ?></span><?php endif; ?><strong><?= e($item['title']) ?></strong><?php if (!empty($item['description'])): ?><p><?= e($item['description']) ?></p><?php endif; ?><?php if (!empty($item['evidence_date'])): ?><small><?= e($item['evidence_date']) ?></small><?php endif; ?></div><?php if (str_starts_with($item['mime_type'],'image/') || in_array($item['mime_type'],['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/msword','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.ms-powerpoint'],true)): ?><button type="button" class="public-evidence-preview" data-evidence-preview data-evidence-url="/p/<?= e($token) ?>/evidence/<?= (int)$item['id'] ?>" data-evidence-title="<?= e($item['title']) ?>" data-evidence-mime="<?= e($item['mime_type']) ?>">استعراض</button><?php endif; ?></article><?php endforeach; ?></div></section><?php endif; ?>
        </article>
        <nav class="section-view-pagination" aria-label="التنقل بين الأقسام"><?php if ($previous): ?><a href="/p/<?= e($token) ?>/section/<?= (int)$previous['id'] ?>">← السابق<span><?= e($previous['title']) ?></span></a><?php else: ?><span></span><?php endif; ?><?php if ($next): ?><a href="/p/<?= e($token) ?>/section/<?= (int)$next['id'] ?>">التالي →<span><?= e($next['title']) ?></span></a><?php endif; ?></nav>
    </main>
<div class="evidence-modal" data-evidence-modal hidden aria-hidden="true"><div class="evidence-modal-backdrop" data-evidence-close></div><div class="evidence-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="evidence-modal-title"><header class="evidence-modal-header"><div><span class="eyebrow"><?= $english?'Evidence from the portfolio':'شاهد من الملف' ?></span><h2 id="evidence-modal-title" data-evidence-modal-title><?= $english?'Evidence preview':'استعراض الشاهد' ?></h2></div><button type="button" class="evidence-modal-close" data-evidence-close aria-label="<?= $english?'Close':'إغلاق' ?>">×</button></header><div class="evidence-modal-body" data-evidence-modal-body></div><footer class="evidence-modal-footer"><a class="button button-outline-navy" data-evidence-download target="_blank" rel="noopener"><?= $english?'Open in new window':'فتح في نافذة جديدة' ?></a><button type="button" class="button button-quiet" data-evidence-close><?= $english?'Close':'إغلاق' ?></button></footer></div></div>
